-- Data for news
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (1, 'India Unveils Next-Gen High-Speed Green Rail Corridor Connecting 8 Mega Hubs', 'भारत ने 8 बड़े केंद्रों को जोड़ने वाले अगली पीढ़ी के हाई-स्पीड ग्रीन रेल कॉरिडोर का अनावरण किया', 'india-unveils-next-gen-high-speed-green-rail-corridor', 'The landmark infrastructure project aims to reduce transit times by 55% while running entirely on dedicated solar and wind renewable grids.', 'इस ऐतिहासिक बुनियादी ढांचा परियोजना का लक्ष्य समर्पित सौर और पवन नवीकरणीय ग्रिड पर चलते हुए यात्रा समय को 55% तक कम करना है।', '<p>In a major leap forward for national infrastructure, the Ministry of Railways today announced the formal launch of the Next-Generation High-Speed Green Rail Corridor, connecting key metropolitan and industrial hubs across the nation.</p>
                <p>The state-of-the-art train network is designed to run at cruising speeds of 280 km/h, slashing travel times between commercial epicenters dramatically. More importantly, 100% of the traction energy will be sourced from dedicated solar parks and coastal wind turbine farms established under the National Clean Transit Directive.</p>
                <h3>Eco-Friendly Engineering</h3>
                <p>Engineers highlighted that the trains will utilize lightweight carbon-composite aerodynamic nose cones and regenerative electromagnetic braking systems, feeding up to 20% of generated deceleration energy back into the auxiliary power supply.</p>
                <blockquote>"This corridor isn\'t merely about speed; it redefines sustainable mass transit for the next half century," stated the Project Director during the inaugural briefing.</blockquote>
                <p>Initial commercial passenger and priority freight runs will commence early next quarter, with affordable tier ticketing ensuring mass accessibility.</p>', '<p>राष्ट्रीय बुनियादी ढांचे के क्षेत्र में एक बड़ी छलांग लगाते हुए, रेल मंत्रालय ने आज देश भर के प्रमुख महानगरीय और औद्योगिक केंद्रों को जोड़ने वाले अगली पीढ़ी के हाई-स्पीड ग्रीन रेल कॉरिडोर के औपचारिक शुभारंभ की घोषणा की।</p>
                <p>यह अत्याधुनिक ट्रेन नेटवर्क 280 किमी/घंटा की गति से चलने के लिए डिज़ाइन किया गया है, जिससे वाणिज्यिक केंद्रों के बीच यात्रा का समय नाटकीय रूप से कम हो जाएगा। इससे भी महत्वपूर्ण बात यह है कि राष्ट्रीय स्वच्छ पारगमन निर्देश के तहत स्थापित समर्पित सौर पार्कों और तटीय पवन टरबाइन फार्मों से 100% ऊर्जा प्राप्त की जाएगी।</p>
                <h3>पर्यावरण-अनुकूल इंजीनियरिंग</h3>
                <p>इंजीनियरों ने रेखांकित किया कि ट्रेनें हल्के कार्बन-कंपोजिट वायुगतिकीय नोज़ कोन और पुनर्योजी विद्युत-चुंबकीय ब्रेकिंग सिस्टम का उपयोग करेंगी, जो उत्पन्न ऊर्जा का 20% तक वापस ग्रिड में फीड करेगा।</p>
                <blockquote>"यह गलियारा केवल गति के बारे में नहीं है; यह अगली आधी सदी के लिए टिकाऊ जन पारगमन को पुनर्परिभाषित करता है," उद्घाटन के दौरान परियोजना निदेशक ने कहा।</blockquote>
                <p>प्रारंभिक वाणिज्यिक यात्री यात्राएं अगली तिमाही में शुरू होंगी, जिसमें किफायती टिकट दरें आम जनता की पहुंच सुनिश्चित करेंगी।</p>', 3, 13, 'https://images.unsplash.com/photo-1474487548417-781cb71495f3?w=1200&auto=format&fit=crop', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 1, 0, 'draft', 1437, '2026-10-31 15:31:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:32:41');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (2, 'ISRO Prepares Breakthrough Lunar Polar Explorer for Deep Ice Cap Drilling', 'इसरो ने गहरे बर्फीले क्रेटर में ड्रिलिंग के लिए चंद्र ध्रुवीय अन्वेषक तैयार किया', 'isro-prepares-breakthrough-lunar-polar-explorer', 'The upcoming lunar mission will carry indigenous thermal drills capable of penetrating 3 meters into permanently shadowed crater basins to extract pristine water ice.', 'आगामी चंद्र मिशन में स्वदेशी थर्मल ड्रिल ले जाई जाएगी जो प्राचीन जल बर्फ निकालने के लिए स्थायी रूप से छाया वाले क्रेटर में 3 मीटर तक प्रवेश करने में सक्षम होगी।', '<p>Building on the resounding global triumph of recent moon explorations, the Indian Space Research Organisation (ISRO) is entering the final testing phase of its Lunar Polar Ice Sampler module.</p>
                <p>The mission targets the treacherous, ultra-frigid craters situated at the Moon’s extreme South Pole, where sunlight never touches the crater floors and temperatures plunge below minus 230 degrees Celsius.</p>
                <h3>Advanced Sub-Surface Probes</h3>
                <p>Equipped with diamond-tipped cryogenic rotary drills, the robotic lander will extract continuous cylindrical cores of lunar permafrost. Onboard mass spectrometers and gas chromatographs will perform real-time chemical assays to quantify isotope ratios and volatile organic compounds.</p>
                <p>Scientists believe these measurements could unravel billion-year-old records of inner solar system cometary bombardments and confirm resources essential for future permanent crewed research habitats.</p>', '<p>हालिया चंद्र अभियानों की शानदार वैश्विक सफलता के बाद, भारतीय अंतरिक्ष अनुसंधान संगठन (इसरो) अपने चंद्र ध्रुवीय बर्फ नमूना मॉड्यूल के अंतिम परीक्षण चरण में प्रवेश कर रहा है।</p>
                <p>मिशन का लक्ष्य चंद्रमा के अत्यधिक दक्षिणी ध्रुव पर स्थित दुर्गम, अति-शीत क्रेटर हैं, जहां सूर्य का प्रकाश कभी क्रेटर के तल तक नहीं पहुंचता है और तापमान शून्य से 230 डिग्री सेल्सियस नीचे चला जाता है।</p>
                <h3>उन्नत सतह-अन्वेषण जांच</h3>
                <p>डायमंड-टिप्ड क्रायोजेनिक रोटरी ड्रिल से लैस, रोबोटिक लैंडर चंद्र पर्माफ्रॉस्ट के बेलनाकार कोर निकालेगा। बोर्ड पर मौजूद मास स्पेक्ट्रोमीटर आइसोटोप अनुपात और वाष्पशील कार्बनिक यौगिकों का विश्लेषण करेंगे।</p>
                <p>वैज्ञानिकों का मानना है कि ये माप सौर मंडल के अरबों साल पुराने रहस्यों को उजागर कर सकते हैं और भविष्य के स्थायी मानव अनुसंधान केंद्रों के लिए आवश्यक संसाधनों की पुष्टि कर सकते हैं।</p>', 8, 16, 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=1200&auto=format&fit=crop', NULL, 1, 1, 'draft', 2391, '2026-10-31 14:36:05', 1, '2026-10-31 15:46:04', '2026-11-04 11:48:28');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (3, 'Global Climate Summit Enacts Binding Cap on Industrial Methane Emissions', 'वैश्विक जलवायु शिखर सम्मेलन में औद्योगिक मीथेन उत्सर्जन पर बाध्यकारी सीमा लागू', 'global-climate-summit-enacts-binding-cap-methane', 'Over 140 nations ratify historic pact to cut super-potent greenhouse gas leakage across oil, gas, agriculture, and municipal landfills by 40%.', '140 से अधिक देशों ने तेल, गैस, कृषि और लैंडफिल में अत्यधिक शक्तिशाली ग्रीनहाउस गैस रिसाव को 40% तक कम करने के ऐतिहासिक समझौते की पुष्टि की।', '<p>In a historic midnight consensus, delegates at the Global Climate Action Forum sealed a multilateral pact imposing strict, verifiable limits on point-source methane discharges.</p>
                <p>Methane, while shorter-lived in the atmosphere than carbon dioxide, possesses over 80 times the heat-trapping potency across a twenty-year timescale. The newly adopted framework mandates continuous satellite monitoring and automated thermal leakage audits across energy extraction pipelines.</p>
                <p>Financial assistance mechanisms totaling $45 billion were pledged to assist emerging economies in upgrading agricultural manure digestion plants and sealing abandoned fossil fuel wells.</p>', '<p>एक ऐतिहासिक मध्यरात्रि सहमति में, ग्लोबल क्लाइमेट एक्शन फोरम के प्रतिनिधियों ने मीथेन डिस्चार्ज पर सख्त और सत्यापन योग्य सीमा लगाने वाले एक बहुपक्षीय समझौते पर मुहर लगाई।</p>
                <p>मीथेन, हालांकि कार्बन डाइऑक्साइड की तुलना में वातावरण में कम समय तक रहती है, लेकिन बीस साल के समय में 80 गुना अधिक गर्मी सोखने की क्षमता रखती है। नए ढांचे में ऊर्जा पाइपलाइनों में उपग्रह निगरानी को अनिवार्य किया गया है।</p>
                <p>विकासशील अर्थव्यवस्थाओं को कृषि बायोगैस संयंत्रों के उन्नयन और पुराने कुओं को सील करने में सहायता के लिए $45 बिलियन की वित्तीय सहायता का संकल्प लिया गया।</p>', 5, NULL, 'https://images.unsplash.com/photo-1611273426858-450d8e3c9fce?w=1200&auto=format&fit=crop', NULL, 0, 1, 'published', 890, '2026-10-31 13:01:05', 1, '2026-10-31 15:46:04', '2026-10-31 15:46:04');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (4, 'Sensex Surges Past Record 85,000 Mark Led by Tech, Banking and Renewable Energy Inflows', 'सेंसेक्स ने टेक, बैंकिंग और रिन्यूएबल शेयरों में भारी निवेश से 85,000 का ऐतिहासिक आंकड़ा पार किया', 'sensex-surges-past-record-85000-mark', 'Domestic institutional investors and foreign portfolios fuel explosive market rally as retail participation in mutual funds touches all-time peaks.', 'घरेलू संस्थागत निवेशकों और विदेशी पोर्टफोलियो ने बाजार में जोरदार तेजी को बढ़ावा दिया, म्यूचुअल फंड में खुदरा भागीदारी सर्वकालिक उच्च स्तर पर पहुंची।', '<p>Bulls charged through Dalal Street today as benchmark indices shattered all previous records. The BSE Sensex closed above the psychological 85,000 milestone, buoyed by robust quarterly earnings across private banks, IT heavyweights, and green energy manufacturers.</p>
                <p>Market analysts attributed the sustained momentum to strong macroeconomic indicators, easing retail inflation, and unprecedented capital expenditure commitments announced for rural digital infrastructure.</p>
                <p>Trading desks reported heavy foreign portfolio buying, with net institutional purchases topping ₹6,800 crore in today\'s trading session alone.</p>', '<p>दलाल स्ट्रीट पर आज जबरदस्त उछाल देखने को मिला और बेंचमार्क सूचकांकों ने पिछले सभी रिकॉर्ड तोड़ दिए। बीएसई सेंसेक्स 85,000 के महत्वपूर्ण स्तर के पार बंद हुआ, जिसे निजी बैंकों, आईटी दिग्गजों और हरित ऊर्जा कंपनियों के मजबूत नतीजों से समर्थन मिला।</p>
                <p>बाजार विश्लेषकों ने इस तेजी का श्रेय मजबूत व्यापक आर्थिक संकेतकों, खुदरा मुद्रास्फीति में कमी और ग्रामीण डिजिटल बुनियादी ढांचे के लिए पूंजीगत व्यय को दिया।</p>
                <p>विदेशी पोर्टफोलियो निवेशकों ने आज के कारोबारी सत्र में ही ₹6,800 करोड़ से अधिक की शुद्ध संस्थागत खरीदारी दर्ज की।</p>', 7, 6, 'https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=1200&auto=format&fit=crop', NULL, 1, 1, 'draft', 3121, '2026-10-31 12:26:05', 1, '2026-10-31 15:46:04', '2026-11-04 11:48:14');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (5, 'Parliament Passes Landmark Digital Healthcare and Telemedicine Equity Act', 'संसद ने ऐतिहासिक डिजिटल स्वास्थ्य सेवा और टेलीमेडिसिन समानता अधिनियम पारित किया', 'parliament-passes-digital-healthcare-act', 'The legislation guarantees high-speed video consultation and doorstep generic medicine delivery across 600,000 villages nationwide.', 'यह कानून देश भर के 600,000 गांवों में हाई-स्पीड वीडियो परामर्श और घर-घर जेनेरिक दवाओं की डिलीवरी की गारंटी देता है।', '<p>Following a constructive bi-partisan debate, both houses of Parliament have passed the comprehensive Digital Healthcare & Telemedicine Equity Act with an overwhelming majority.</p>
                <p>The landmark bill establishes digital primary health centers in every Gram Panchayat, staffed by certified healthcare associates and integrated with AI diagnostic kiosks. Patients can connect directly with super-specialists at premier medical institutes without traveling hundreds of miles.</p>
                <p>The health minister emphasized that digital prescriptions will be seamlessly linked to PM Jan Aushadhi generic distribution channels, reducing out-of-pocket medical expenses for rural families by up to 70%.</p>', '<p>संसद के दोनों सदनों ने भारी बहुमत से व्यापक डिजिटल स्वास्थ्य सेवा और टेलीमेडिसिन समानता अधिनियम पारित कर दिया है।</p>
                <p>यह ऐतिहासिक विधेयक प्रत्येक ग्राम पंचायत में डिजिटल प्राथमिक स्वास्थ्य केंद्र स्थापित करता है, जहां प्रमाणित स्वास्थ्य कर्मी होंगे और जो एआई डायग्नोस्टिक कियोस्क से एकीकृत होंगे। मरीज सैकड़ों मील की यात्रा किए बिना प्रमुख चिकित्सा संस्थानों के विशेषज्ञों से सीधे जुड़ सकेंगे।</p>
                <p>स्वास्थ्य मंत्री ने जोर देकर कहा कि डिजिटल नुस्खे निर्बाध रूप से जन औषधि केंद्रों से जुड़े होंगे, जिससे ग्रामीण परिवारों के इलाज का खर्च 70% तक कम हो जाएगा।</p>', 6, 10, 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=1200&auto=format&fit=crop', NULL, 0, 0, 'draft', 1181, '2026-10-31 11:36:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:34:44');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (6, 'Lucknow Metro Completes Underground Extension Connecting Historic Old City to Airport', 'लखनऊ मेट्रो ने पुराने शहर को हवाई अड्डे से जोड़ने वाले भूमिगत विस्तार को पूरा किया', 'lucknow-metro-completes-underground-extension', 'Commuters in Lucknow can now travel from Chowk to Chaudhary Charan Singh International Airport in under 26 minutes with contactless ticketing.', 'लखनऊ के यात्री अब चौक से चौधरी चरण सिंह अंतर्राष्ट्रीय हवाई अड्डे तक बिना किसी संपर्क के टिकट लेकर 26 मिनट से भी कम समय में यात्रा कर सकते हैं।', '<p>The capital of Uttar Pradesh marked a major transit milestone today with the trial completion of the 11.2 km underground metro segment threading through the historic corridors of Old Lucknow.</p>
                <p>Designed with architectural motifs honoring Awadhi heritage, the newly constructed subterranean stations feature state-of-the-art tunnel ventilation and automated platform screen doors.</p>
                <p>Urban planners project that the corridor will eliminate over 45,000 vehicular trips daily along congested arterial roads like MG Marg and Ring Road, cutting urban air particulate pollution significantly.</p>', '<p>उत्तर प्रदेश की राजधानी ने आज पुराने लखनऊ के ऐतिहासिक गलियारों से गुजरने वाले 11.2 किलोमीटर के भूमिगत मेट्रो खंड के परीक्षण के साथ एक बड़ा मील का पत्थर हासिल किया।</p>
                <p>अवधी विरासत को सम्मान देने वाले स्थापत्य रूपांकनों के साथ डिज़ाइन किए गए इन नवनिर्मित स्टेशनों में अत्याधुनिक सुरंग वेंटिलेशन और स्वचालित स्क्रीन दरवाजे शामिल हैं।</p>
                <p>नियोजकों का अनुमान है कि यह गलियारा एमजी मार्ग और रिंग रोड जैसी भीड़भाड़ वाली सड़कों पर प्रतिदिन 45,000 से अधिक वाहनों की यात्रा को कम करेगा, जिससे शहरी प्रदूषण में भारी कमी आएगी।</p>', 3, 1, 'https://res.cloudinary.com/oez9muz3/image/upload/v1793873717/janpulse/news/dk5hmbc72sworowrrnys.jpg', NULL, 0, 1, 'published', 943, '2026-10-31 10:46:05', 1, '2026-10-31 15:46:04', '2026-11-05 15:45:19');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (7, 'Mumbai Coastal Road Phase 2 Opens to Traffic: Marine Drive to Kandivali in 40 Minutes', 'मुंबई कोस्टल रोड फेज़ 2 यातायात के लिए खुला: मरीन ड्राइव से कांदिवली 40 मिनट में', 'mumbai-coastal-road-phase-2-opens', 'The undersea tunnel and sea link bridges revolutionize Western Mumbai commutes with scenic seaside promenades and dedicated EV charging corridors.', 'समुद्र के नीचे बनी सुरंग और सी-लिंक पुलों ने पश्चिमी मुंबई के आवागमन में क्रांति ला दी है, जिसमें सुंदर सैरगाह और ईवी चार्जिंग कॉरिडोर शामिल हैं।', '<p>Western suburban commuters in Mumbai experienced unprecedented relief this morning as the second phase of the ambitious Coastal Road project was formally commissioned for regular vehicular traffic.</p>
                <p>The engineering marvel features twin twin-lane undersea tunnels bored beneath the Arabian seabed, coupled with elevated viaducts offering panoramic vistas of the Arabian Sea shoreline.</p>
                <p>Traffic monitoring centers recorded smooth average vehicle flows of 75 km/h, slashing what used to be an exhausting two-hour peak gridlock into a brisk 38-minute drive.</p>', '<p>मुंबई में पश्चिमी उपनगरीय यात्रियों को आज सुबह अभूतपूर्व राहत मिली जब महत्वाकांक्षी तटीय सड़क परियोजना के दूसरे चरण को नियमित यातायात के लिए चालू किया गया।</p>
                <p>इस इंजीनियरिंग चमत्कार में अरब सागर के नीचे खोदी गई दोहरी लेन वाली समुद्र के नीचे की सुरंगें हैं, साथ ही समुद्र तट के मनोरम दृश्य प्रस्तुत करने वाले एलिवेटेड पुल शामिल हैं।</p>
                <p>यातायात केंद्रों ने 75 किमी/घंटा का सुचारू प्रवाह दर्ज किया, जिससे दो घंटे का भारी जाम केवल 38 मिनट की सुखद यात्रा में बदल गया।</p>', 3, 7, 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=1200&auto=format&fit=crop', NULL, 0, 0, 'published', 1678, '2026-10-31 09:16:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:09:03');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (8, 'ICC Champions Trophy: Team India Clinches Dramatic Last-Over Victory with Brilliant Bowling', 'आईसीसी चैंपियंस ट्रॉफी: शानदार गेंदबाजी से टीम इंडिया ने आखिरी ओवर में रोमांचक जीत दर्ज की', 'icc-champions-trophy-india-dramatic-victory', 'Defending 12 runs in the tense final over, Jasprit Bumrah produces three consecutive yorkers to send the stadium into wild celebrations.', 'तनावपूर्ण अंतिम ओवर में 12 रनों का बचाव करते हुए, जसप्रीत बुमराह ने लगातार तीन सटीक यॉर्कर फेंककर पूरे स्टेडियम को जश्न में डुबो दिया।', '<p>In one of the most heart-stopping climaxes in recent cricket history, Team India edged out rivals in a nail-biting encounter at the packed stadium tonight.</p>
                <p>Having posted a competitive 287 on a wearing pitch thanks to a sublime century by the vice-captain, the match seemed to be slipping away in the death overs as the opposition lower order launched a spirited counter-attack.</p>
                <p>However, bowling the decisive 50th over, spearhead Jasprit Bumrah delivered a masterclass in reverse swing and pinpoint yorkers, conceding just four runs and claiming two wickets to seal an unforgettable triumph.</p>', '<p>क्रिकेट इतिहास के सबसे रोमांचक मुकाबलों में से एक में, टीम इंडिया ने आज रात खचाखच भरे स्टेडियम में कड़े मुकाबले में जीत हासिल की।</p>
                <p>उप-कप्तान के शानदार शतक की बदौलत धीमी पिच पर 287 रन बनाने के बाद, मैच अंतिम ओवरों में हाथ से फिसलता दिख रहा था जब विपक्षी बल्लेबाजों ने तेज प्रहार शुरू कर दिए।</p>
                <p>हालाँकि, निर्णायक 50वां ओवर फेंकते हुए, जसप्रीत बुमराह ने रिवर्स स्विंग और यॉर्कर का अद्भुत प्रदर्शन किया, केवल चार रन दिए और दो विकेट लेकर जीत पक्की की।</p>', 7, NULL, 'https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?w=1200&auto=format&fit=crop', NULL, 0, 0, 'draft', 4582, '2026-10-31 08:46:05', 1, '2026-10-31 15:46:04', '2026-11-04 11:47:20');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (9, 'AI Generative Models Achieve Real-Time Multilingual Simultaneous Voice Translation', 'एआई जेनरेटिव मॉडल ने रीयल-टाइम बहुभाषी वॉयस ट्रांसलेशन में हासिल की बड़ी सफलता', 'ai-models-achieve-real-time-multilingual-translation', 'New ultra-low latency transformer architecture enables conversations across 35 languages while preserving natural vocal pitch, cadence, and emotion.', 'नए अल्ट्रा-लो लेटेंसी आर्किटेक्चर ने आवाज की पिच, टोन और भावना को बनाए रखते हुए 35 भाषाओं में बातचीत को संभव बना दिया है।', '<p>Artificial intelligence researchers have published groundbreaking results demonstrating instantaneous, fluid speech-to-speech translation with sub-100-millisecond latency.</p>
                <p>Unlike previous multi-stage cascades (speech-to-text, translation, text-to-speech), the new end-to-end neural system directly transforms audio acoustic waves from the source language into target language phonemes, preserving the speaker\'s emotional nuance and natural vocal identity.</p>
                <p>Educational and medical sectors across rural multilingual regions are anticipated to be the immediate beneficiaries of this democratizing innovation.</p>', '<p>आर्टिफिशियल इंटेलिजेंस शोधकर्ताओं ने 100-मिलीसेकंड से कम समय में तात्कालिक, धाराप्रवाह भाषण-से-भाषण अनुवाद प्रदर्शित करने वाले अभूतपूर्व परिणाम प्रकाशित किए हैं।</p>
                <p>पुरानी प्रणालियों के विपरीत, नया न्यूरल सिस्टम स्रोत भाषा से सीधे लक्षित भाषा की ध्वनि तरंगों में ऑडियो को बदलता है, जिससे वक्ता की भावना और प्राकृतिक आवाज सुरक्षित रहती है।</p>
                <p>ग्रामीण बहुभाषी क्षेत्रों में शैक्षिक और चिकित्सा क्षेत्रों को इस नवाचार का तत्काल लाभार्थी माना जा रहा है।</p>', 8, 17, 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1200&auto=format&fit=crop', NULL, 0, 0, 'draft', 1890, '2026-10-31 07:31:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:07:34');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (10, 'National Film Awards Announced: Pan-India Epics and Indie Social Dramas Sweep Honors', 'राष्ट्रीय फिल्म पुरस्कारों की घोषणा: पैन-इंडिया महाकाव्यों और सामाजिक नाटकों का दबदबा', 'national-film-awards-announced-honors', 'Jury celebrates cinematic brilliance across Hindi, Tamil, Malayalam, and Bengali languages, recognizing realistic grassroots storytelling.', 'जूरी ने जमीनी स्तर की यथार्थवादी कहानियों को पहचानते हुए हिंदी, तमिल, मलयालम और बंगाली भाषाओं में सिनेमाई उत्कृष्टता का सम्मान किया।', '<p>The prestigious National Film Awards were officially unveiled today at an illustrious ceremony in New Delhi, celebrating diverse voices and groundbreaking cinematic vision across India\'s vibrant regional film industries.</p>
                <p>The coveted Best Feature Film trophy was awarded to a critically lauded indie drama chronicling the resilient spirit of rural women farmers, while Best Actor honors were jointly conferred upon two powerhouse performances in historical and modern psychological thrillers.</p>
                <p>Critics applauded the selection committee for spotlighting emerging storytellers alongside big-budget technical masterpieces.</p>', '<p>प्रतिष्ठित राष्ट्रीय फिल्म पुरस्कारों की आधिकारिक घोषणा आज नई दिल्ली में एक भव्य समारोह में की गई, जिसमें भारत के जीवंत क्षेत्रीय सिनेमा की विविधता का सम्मान किया गया।</p>
                <p>सर्वश्रेष्ठ फीचर फिल्म की प्रतिष्ठित ट्रॉफी ग्रामीण महिला किसानों के संघर्ष पर आधारित एक सामाजिक नाटक को दी गई, जबकि सर्वश्रेष्ठ अभिनेता का पुरस्कार संयुक्त रूप से ऐतिहासिक और मनोवैज्ञानिक थ्रिलर के कलाकारों को मिला।</p>
                <p>आलोचकों ने बड़े बजट की फिल्मों के साथ-साथ उभरते हुए स्वतंत्र निर्देशकों को प्रोत्साहित करने के लिए जूरी की सराहना की।</p>', 10, 10, 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=1200&auto=format&fit=crop', NULL, 0, 0, 'draft', 2243, '2026-10-31 06:06:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:07:04');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (11, 'Medical Breakthrough: Indigenous CAR-T Cell Therapy Approved for Low-Cost Cancer Treatment', 'चिकित्सा जगत में क्रांति: कम लागत वाले कैंसर उपचार के लिए स्वदेशी CAR-T सेल थेरेपी को मंजूरी', 'indigenous-car-t-cell-therapy-approved', 'Revolutionary targeted immunotherapy developed by top bio-engineers reduces advanced leukemia treatment expenses by up to 90%.', 'शीर्ष बायो-इंजीनियरों द्वारा विकसित क्रांतिकारी इम्यूनोथेरेपी ने ल्यूकेमिया के इलाज के खर्च को 90% तक कम कर दिया है।', '<p>In a historic victory for affordable oncology, the Central Drugs Standard Control Organisation (CDSCO) has granted full regulatory approval for commercial manufacture of the nation\'s first indigenous CAR-T cell immunotherapy.</p>
                <p>The therapy involves genetically reprogramming a patient\'s own T-cells in specialized bioreactors to specifically target and eradicate malignant cancer cells without damaging healthy tissues.</p>
                <p>Previously costing over ₹3 crore abroad, the homegrown solution brings this life-saving protocol down to under ₹25 lakh, with public hospital subsidies bringing it within reach of underprivileged patients.</p>', '<p>सस्ती कैंसर चिकित्सा के लिए एक ऐतिहासिक सफलता में, केंद्रीय औषधि मानक नियंत्रण संगठन (सीडीएससीओ) ने देश की पहली स्वदेशी CAR-T सेल इम्यूनोथेरेपी को पूर्ण मंजूरी दे दी है।</p>
                <p>इस थेरेपी में मरीज की अपनी टी-कोशिकाओं को आनुवंशिक रूप से रीप्रोग्राम किया जाता है ताकि वे स्वस्थ ऊतकों को नुकसान पहुंचाए बिना कैंसर कोशिकाओं को नष्ट कर सकें।</p>
                <p>विदेशों में ₹3 करोड़ से अधिक खर्च वाली यह तकनीक अब ₹25 लाख से कम में उपलब्ध होगी, और सरकारी अस्पतालों में सब्सिडी के साथ गरीबों के लिए भी सुलभ होगी।</p>', 11, 6, 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=1200&auto=format&fit=crop', NULL, 1, 0, 'draft', 1730, '2026-10-31 04:36:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:07:55');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (12, 'Patna AIIMS Inaugurates Advanced Neonatal Critical Care Center with 200 Beds', 'एम्स पटना ने 200 बिस्तरों वाले उन्नत नवजात क्रिटिकल केयर सेंटर का उद्घाटन किया', 'patna-aiims-inaugurates-advanced-neonatal-center', 'Equipped with robotic incubators and ECMO units, the super-specialty wing will provide free tertiary treatment to high-risk infants from Bihar and neighboring states.', 'रोबोटिक इनक्यूबेटर और ईसीएमओ इकाइयों से लैस, यह सुपर-स्पेशियलिटी विंग बिहार और पड़ोसी राज्यों के नवजात शिशुओं को मुफ्त तृतीयक उपचार प्रदान करेगा।', '<p>A massive fillip was delivered to pediatric healthcare in Eastern India today as AIIMS Patna commissioned its state-of-the-art Neonatal and Pediatric Intensive Care Complex.</p>
                <p>The facility features 200 micro-filtered negative-pressure beds, round-the-clock point-of-care ultrasound, and dedicated air ambulance transport links for remote rural districts.</p>
                <p>State authorities reiterated that all emergency pediatric services will be covered completely under cashless universal health schemes.</p>', '<p>एम्स पटना ने आज अपने अत्याधुनिक नवजात और बाल चिकित्सा गहन देखभाल परिसर की शुरुआत करके पूर्वी भारत में बाल स्वास्थ्य सेवा को मजबूत किया।</p>
                <p>इस केंद्र में 200 माइक्रो-फ़िल्टर्ड नेगेटिव-प्रेशर बेड, 24 घंटे अल्ट्रासाउंड और दूरदराज के जिलों के लिए एयर एम्बुलेंस की सुविधा है।</p>
                <p>राज्य के अधिकारियों ने दोहराया कि सभी आपातकालीन बाल चिकित्सा सेवाएं कैशलेस स्वास्थ्य योजनाओं के तहत पूरी तरह से मुफ्त होंगी।</p>', 3, 13, 'https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1200&auto=format&fit=crop', NULL, 0, 0, 'published', 810, '2026-10-31 02:26:05', 1, '2026-10-31 15:46:04', '2026-10-31 15:46:04');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (13, 'Varanasi Launches Zero-Emission Solar Ferry Fleet on Holy River Ganga', 'वाराणसी में पवित्र गंगा नदी पर शून्य-उत्सर्जन सौर नौका बेड़े का संचालन शुरू', 'varanasi-launches-solar-ferry-fleet-ganga', 'Silent, solar-powered catamarans now carry pilgrims and tourists along the 84 ghats from Assi to Rajghat without noise or water pollution.', 'मौन, सौर-संचालित कैटामारन अब बिना किसी शोर या जल प्रदूषण के अस्सी से राजघाट तक 84 घाटों पर श्रद्धालुओं और पर्यटकों को ले जा रहे हैं।', '<p>In a tranquil blend of timeless spirituality and cutting-edge renewable technology, Varanasi today inaugurated a brand-new fleet of twenty solar-electric passenger catamarans across the Ganga.</p>
                <p>Each vessel is capped with high-efficiency flexible monocrystalline solar arrays feeding lithium iron phosphate batteries, guaranteeing silent, zero-emission travel along the world-famous ghats.</p>
                <p>Pilgrims expressed delight at experiencing the evening Ganga Aarti without the acoustic roar and diesel exhaust fumes of obsolete motor boats.</p>', '<p>शाश्वत आध्यात्मिकता और नवीकरणीय तकनीक के संगम में, वाराणसी में आज गंगा पर बीस सोलर-इलेक्ट्रिक यात्री नावों के एक नए बेड़े का उद्घाटन किया गया।</p>
                <p>प्रत्येक नाव मोनोक्रिस्टलाइन सौर पैनलों से सुसज्जित है जो लिथियम बैटरी को चार्ज करती हैं, जिससे विश्व प्रसिद्ध घाटों के साथ मौन और प्रदूषण मुक्त यात्रा सुनिश्चित होती है।</p>
                <p>श्रद्धालुओं ने पुराने डीजल इंजनों के धुएं और तेज आवाज के बिना शाम की दिव्य गंगा आरती का अनुभव करने पर खुशी व्यक्त की।</p>', 3, 3, 'https://images.unsplash.com/photo-1561361513-2d000a50f0dc?w=1200&auto=format&fit=crop', NULL, 0, 1, 'draft', 1322, '2026-10-31 00:46:05', 1, '2026-10-31 15:46:04', '2026-11-04 12:35:02');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (14, 'Draft Policy on Urban Aerial Drone Corridors Under Internal Ministry Review', 'शहरी हवाई ड्रोन गलियारों पर मसौदा नीति आंतरिक मंत्रालय की समीक्षा के अधीन', 'draft-policy-urban-aerial-drone-corridors', 'Proposed safety framework for commercial drone logistics is currently undergoing technical validation before public comment period.', 'वाणिज्यिक ड्रोन रसद के लिए प्रस्तावित सुरक्षा ढांचा वर्तमान में सार्वजनिक समीक्षा से पहले तकनीकी सत्यापन के दौर से गुजर रहा है।', '<p>This is an internal working draft outlining altitude ceilings and automated geofencing protocols for delivery unmanned aerial vehicles. It will be scheduled for formal release after stakeholder consensus.</p>', '<p>यह डिलीवरी ड्रोन के लिए ऊंचाई सीमा और स्वचालित जियोफेंसिंग प्रोटोकॉल की रूपरेखा तैयार करने वाला एक आंतरिक मसौदा है। इसे हितधारकों की सहमति के बाद औपचारिक रूप से जारी किया जाएगा।</p>', 8, NULL, 'https://images.unsplash.com/photo-1527977966376-1c8408f9f108?w=1200&auto=format&fit=crop', NULL, 0, 0, 'draft', 2, NULL, 1, '2026-10-31 15:46:04', '2026-11-04 13:58:02');
INSERT INTO `news` (`id`, `title_en`, `title_hi`, `slug`, `excerpt_en`, `excerpt_hi`, `content_en`, `content_hi`, `category_id`, `location_id`, `image_url`, `video_url`, `is_breaking`, `is_featured`, `status`, `views_count`, `published_at`, `created_by`, `created_at`, `updated_at`) VALUES (15, 'Secret Exclusive Draft Investigation 2026', 'गोपनीय विशेष मसौदा जांच 2026', 'secret-exclusive-draft-investigation-2026', 'This is a test draft excerpt that must remain private.', 'यह एक परीक्षण मसौदा संक्षेप है जिसे निजी रहना चाहिए।', '<p>Private confidential news draft.</p>', '<p>निजी गोपनीय समाचार मसौदा।</p>', 1, NULL, 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=1200', NULL, 0, 0, 'draft', 0, NULL, 1, '2026-10-31 15:55:42', '2026-10-31 15:55:42');
